//        cron (every minute)               -> sends reminders that are due
//   3. Widgets (Scriptable) and quick add from Siri / Shortcuts, by private key
//        POST /widget/key                  -> { key }   (signed-in app only)
//        GET  /widget?k=KEY                -> today's data for the widget
//        GET|POST /add?k=KEY&text=\u2026        -> puts a task in the Kairos inbox
//        POST /inbox                       -> the app collects (and clears) the inbox (+ Health numbers)
//        GET|POST /hk?k=KEY&d=\u2026&steps=\u2026    -> Apple Health numbers from the iOS Shortcut
//   GET /health -> setup check
//
// Settings \u203A Variables and Secrets of the Worker:
//   ALLOWED_ORIGINS       = https://phatcharayantapanich.github.io
//   FIREBASE_PROJECT_ID   = kairos-f21ca        (only your signed-in Kairos account can use it)
//   ALLOWED_EMAILS        = you@gmail.com       (optional, comma separated)
//   GOOGLE_CLIENT_ID / GOOGLE_CLIENT_SECRET (Secret) \u2014 only for "permanent Google connection"
// Notifications + widgets also need:
//   Settings \u203A Bindings \u203A KV namespace, variable name KAIROS
//   Settings \u203A Triggers \u203A Cron Triggers \u203A every minute ( * * * * * )

const enc = new TextEncoder();
const b64u = (s) => Uint8Array.from(atob(String(s).replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(String(s).length / 4) * 4, '=')), (c) => c.charCodeAt(0));
